begin;
do $$
declare u uuid;org uuid;office uuid=gen_random_uuid();a uuid=gen_random_uuid();b uuid=gen_random_uuid();outsider uuid=gen_random_uuid();d uuid=gen_random_uuid();d2 uuid=gen_random_uuid();req uuid=gen_random_uuid();thread uuid;r jsonb;reject boolean;n integer;
begin
 select id,organization_id into u,org from public.business_units where code='fahrdienst' and active limit 1;
 insert into auth.users(id,email) values(office,'message-'||office||'@example.invalid'),(a,'message-'||a||'@example.invalid'),(b,'message-'||b||'@example.invalid'),(outsider,'message-'||outsider||'@example.invalid');
 insert into public.app_profiles(id,organization_id,email,full_name,active) values(office,org,'message-'||office||'@example.invalid','Test office',true),(a,org,'message-'||a||'@example.invalid','Test driver',true),(b,org,'message-'||b||'@example.invalid','Test driver 2',true),(outsider,org,'message-'||outsider||'@example.invalid','Test outsider',true);
 insert into public.drivers(id,organization_id,full_name) values(d,org,'Synthetic driver'),(d2,org,'Synthetic driver 2');insert into public.driver_business_units(driver_id,business_unit_id) values(d,u),(d2,u);
 insert into public.memberships(user_id,business_unit_id,role,driver_id,active) values(office,u,'office',null,true),(a,u,'driver',d,true),(b,u,'driver',d2,true);
 r=public.messaging_conversation(u,office,d,null);if r->'thread'<>'null'::jsonb or jsonb_array_length(r->'rows')<>0 then raise exception 'Opening empty chat writes thread';end if;
 r=public.messaging_send(u,office,d,req,' Office message ');perform public.messaging_send(u,office,d,req,'Office message');
 if (select count(*) from public.internal_messages where id=req)<>1 then raise exception 'Duplicate send';end if;
 reject=false;begin perform public.messaging_send(u,office,d,req,'Changed');exception when others then reject=true;end;if not reject then raise exception 'Changed retry accepted';end if;
 r=public.messaging_list(u,a,0);if (r->>'unread')::integer<>1 or jsonb_array_length(r->'contacts')<>1 then raise exception 'Driver unread or directory leaked';end if;
 thread=(r->'threads'->0->>'id')::uuid;
 reject=false;begin perform public.messaging_conversation(u,b,d,null);exception when others then reject=true;end;if not reject then raise exception 'Other driver reads chat';end if;
 reject=false;begin perform public.messaging_send(u,b,d,gen_random_uuid(),'Forbidden');exception when others then reject=true;end;if not reject then raise exception 'Other driver sends';end if;
 reject=false;begin perform public.messaging_mark_read(u,b,d,1);exception when others then reject=true;end;if not reject then raise exception 'Other driver marks read';end if;
 reject=false;begin perform public.messaging_list(u,outsider,0);exception when others then reject=true;end;if not reject then raise exception 'Outsider inbox';end if;
 reject=false;begin perform public.messaging_send(u,a,d,gen_random_uuid(),repeat('x',5001));exception when others then reject=true;end;if not reject then raise exception 'Oversized message';end if;
 perform public.messaging_send(u,a,d,gen_random_uuid(),'Driver reply');perform public.messaging_send(u,office,d,gen_random_uuid(),'New office message');
 perform public.messaging_mark_read(u,a,d,1);r=public.messaging_list(u,a,0);if (r->>'unread')::integer<>1 then raise exception 'Read receipt swallowed unseen later message';end if;
 perform public.messaging_mark_read(u,a,d,3);perform public.messaging_mark_read(u,a,d,1);
 if (select driver_read_sequence from public.message_threads where id=thread)<>3 or (select driver_read_by from public.message_threads where id=thread)<>a then raise exception 'Receipt regressed or actor missing';end if;
 r=public.messaging_list(u,office,0);if (r->>'unread')::integer<>1 then raise exception 'Office unread count wrong';end if;
 perform public.messaging_mark_read(u,office,d,2);
 reject=false;begin perform public.messaging_mark_read(u,office,d,4);exception when others then reject=true;end;if not reject then raise exception 'Future receipt';end if;
 for n in 1..52 loop perform public.messaging_send(u,office,d,gen_random_uuid(),'Synthetic page '||n);end loop;
 r=public.messaging_conversation(u,a,d,null);if jsonb_array_length(r->'rows')<>50 or (r->'rows'->0->>'sequence')::integer<>6 or not (r->>'has_older')::boolean then raise exception 'Latest page truncated incorrectly';end if;
 r=public.messaging_conversation(u,a,d,6);if jsonb_array_length(r->'rows')<>5 or (r->>'has_older')::boolean then raise exception 'Older page incorrect';end if;
 perform public.messaging_send(u,office,d2,gen_random_uuid(),'Other conversation');
 perform set_config('request.jwt.claim.sub',a::text,true);execute 'set local role authenticated';
 if (select count(*) from public.internal_messages where business_unit_id=u)<>55 or exists(select 1 from public.message_threads where driver_id=d2) then raise exception 'RLS driver leaks other chat';end if;
 reject=false;begin update public.message_threads set driver_read_sequence=last_sequence where id=thread;exception when insufficient_privilege then reject=true;end;if not reject then raise exception 'Direct read-state write granted';end if;
 reject=false;begin perform public.messaging_send(u,a,d,gen_random_uuid(),'Direct RPC');exception when insufficient_privilege then reject=true;end;if not reject then raise exception 'Browser can call privileged RPC';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',office::text,true);execute 'set local role authenticated';
 if (select count(*) from public.internal_messages where id=req)<>1 then raise exception 'Office cannot read';end if;execute 'reset role';
 perform set_config('request.jwt.claim.sub',outsider::text,true);execute 'set local role authenticated';if exists(select 1 from public.internal_messages where business_unit_id=u) then raise exception 'Outsider RLS leak';end if;execute 'reset role';
 update public.memberships set active=false where user_id=a and business_unit_id=u;
 reject=false;begin perform public.messaging_list(u,a,0);exception when others then reject=true;end;if not reject then raise exception 'Inactive account access';end if;
 reject=false;begin perform public.messaging_send(u,office,d,gen_random_uuid(),'Inactive target');exception when others then reject=true;end;if not reject then raise exception 'Inactive target accepts new sends';end if;
 r=public.messaging_conversation(u,office,d,null);if (r->>'can_send')::boolean then raise exception 'Inactive target marked available';end if;
 reject=false;begin update public.internal_messages set body='overwrite' where id=req;exception when others then reject=true;end;if not reject then raise exception 'Message mutable';end if;
 execute 'set local role anon';reject=false;begin perform id from public.internal_messages;exception when insufficient_privilege then reject=true;end;if not reject then raise exception 'Anonymous chat access';end if;execute 'reset role';
end;$$;
rollback;
